 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Two horizontal color sequences in bottom row define the motifs.
    row=g[-1]
    nz=[i for i,v in enumerate(row) if v]
    # Split at the blank gap into consecutive nonzero runs.
    runs=[]
    for i in nz:
        if not runs or i>runs[-1][-1]+1: runs.append([i])
        else: runs[-1].append(i)
    motifs=[[row[i] for i in r] for r in runs]
    # Markers are singleton cells not on the motif row. At each marker, place each motif
    # beginning at the marker coordinate; motif direction is left-to-right, anchor is first.
    for r in range(h-1):
        for c in range(w):
            if g[r][c]:
                # infer motif by marker identity: first pattern begins with marker color,
                # second pattern also selected where the marker corresponds to its first color.
                # Use observed convention: each marker receives the sequence whose first color matches it,
                # otherwise matching colors appearing in the motif determine start offset.
                for motif in motifs:
                    if g[r][c] in motif:
                        k=motif.index(g[r][c])
                        start=c-k
                        for j,v in enumerate(motif):
                            cc=start+j
                            if 0<=cc<w: g[r][cc]=v
                        break
    return g
